result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/richmodel/src/doc.ts", "content": "/**
 * Rich-text document model: a flat text string plus a set of mark ranges.
 *
 * A mark range is {from, to, type, attrs?} with from < to and positions
 * indexing into `text` (0-based, `to` exclusive). Ranges are kept normalized:
 * sorted by `from`, never empty, adjacent identical ranges merged.
 *
 * Every public operation mutates the doc in place and returns a concrete
 * inverse operation that, when applied via applyOp, restores the previous
 * state (and itself yields an inverse suitable for redo).
 */

export interface MarkAttrs {
  [key: string]: unknown;
}

export interface MarkRange {
  from: number;
  to: number;
  type: string;
  attrs?: MarkAttrs;
}

export interface Doc {
  text: string;
  marks: MarkRange[];
}

/** Primitive steps an operation is composed of. */
export type Step =
  | { t: 'insert'; pos: number; str: string }
  | { t: 'delete'; from: number; to: number; str: string }
  /** Replaces the entire mark set (used where splitting/merging occurs). */
  | { t: 'setMarks'; marks: MarkRange[] };

export interface Op {
  steps: Step[];
}

/**
 * Per-type inclusivity flag: when text is inserted exactly at a mark's
 * start or end boundary, inclusive marks (bold, italic) grow to cover the
 * inserted text; non-inclusive marks (link) do not — the insertion lands
 * outside them.
 */
export const MARK_INCLUSIVE: Record<string, boolean> = {
  bold: true,
  italic: true,
  link: false,
};

export function isInclusive(type: string): boolean {
  return MARK_INCLUSIVE[type] ?? false;
}

export function createEmptyDoc(text = ''): Doc {
  return { text, marks: [] };
}

// ---------------------------------------------------------------------------
// helpers
// ---------------------------------------------------------------------------

function attrsEqual(a?: MarkAttrs, b?: MarkAttrs): boolean {
  const ka = Object.keys(a ?? {}).sort();
  const kb = Object.keys(b ?? {}).sort();
  if (ka.length !== kb.length) return false;
  for (let i = 0; i < ka.length; i++) {
    if (ka[i] !== kb[i]) return false;
    if ((a ?? {})[ka[i]!] !== (b ?? {})[kb[i]!]) return false;
  }
  return true;
}

export function cloneMarks(marks: MarkRange[]): MarkRange[] {
  return marks.map((m) => ({
    ...m,
    ...(m.attrs ? { attrs: { ...m.attrs } } : {}),
  }));
}

export function cloneDoc(doc: Doc): Doc {
  return { text: doc.text, marks: cloneMarks(doc.marks) };
}

/** Drop empty ranges, sort by position, merge adjacent/overlapping identical ranges. */
export function normalizeMarks(marks: MarkRange[]): MarkRange[] {
  const sorted = marks
    .filter((m) => m.to > m.from)
    .slice()
    .sort((a, b) => a.from - b.from || a.to - b.to);
  const out: MarkRange[] = [];
  for (const m of sorted) {
    const last = out[out.length - 1];
    if (
      last &&
      last.type === m.type &&
      attrsEqual(last.attrs, m.attrs) &&
      last.to >= m.from
    ) {
      last.to = Math.max(last.to, m.to);
    } else {
      out.push({ ...m, ...(m.attrs ? { attrs: { ...m.attrs } } : {}) });
    }
  }
  return out;
}

/** Pieces of mark range `m` after removing the half-open interval [from, to). */
function subtractRange(m: MarkRange, from: number, to: number): MarkRange[] {
  if (to <= m.from || from >= m.to) return [{ ...m }];
  const pieces: MarkRange[] = [];
  if (m.from < from) pieces.push({ ...m, to: from });
  if (m.to > to) pieces.push({ ...m, from: Math.max(from, m.from) });
  return pieces;
}

// ---------------------------------------------------------------------------
// core executor: applies an op, returns its concrete inverse
// ---------------------------------------------------------------------------

export function applyOp(doc: Doc, op: Op): Op {
  const invSteps: Step[] = [];
  for (const step of op.steps) {
    if (step.t === 'insert') {
      invSteps.unshift({
        t: 'delete',
        from: step.pos,
        to: step.pos + step.str.length,
        str: step.str,
      });
      insertTextMut(doc, step.pos, step.str);
    } else if (step.t === 'delete') {
      invSteps.unshift({ t: 'insert', pos: step.from, str: step.str });
      // Deletion can trim, split or drop marks; snapshot for exact restore.
      invSteps.unshift({ t: 'setMarks', marks: cloneMarks(doc.marks) });
      deleteRangeMut(doc, step.from, step.to);
    } else {
      invSteps.unshift({ t: 'setMarks', marks: cloneMarks(doc.marks) });
      doc.marks = cloneMarks(step.marks);
    }
  }
  return { steps: invSteps };
}

// ---------------------------------------------------------------------------
// mutators (position/mark bookkeeping)
// ---------------------------------------------------------------------------

function insertTextMut(doc: Doc, pos: number, str: string): void {
  const L = str.length;
  doc.text = doc.text.slice(0, pos) + str + doc.text.slice(pos);
  for (const m of doc.marks) {
    if (pos < m.from) {
      // entirely before the mark: shift it right
      m.from += L;
      m.to += L;
    } else if (pos > m.from && pos < m.to) {
      // strictly inside: the mark grows
      m.to += L;
    } else if (pos === m.from) {
      if (isInclusive(m.type)) {
        m.to += L; // inclusive: inserted text joins the mark
      } else {
        m.from += L; // non-inclusive: insertion lands before the mark
        m.to += L;
      }
    } else if (pos === m.to) {
      if (isInclusive(m.type)) {
        m.to += L; // inclusive: mark extends over the insertion
      }
      // non-inclusive: unchanged, insertion lands after the mark
    }
  }
}

function deleteRangeMut(doc: Doc, from: number, to: number): void {
  const D = to - from;
  doc.text = doc.text.slice(0, from) + doc.text.slice(to);
  const next: MarkRange[] = [];
  for (const m of doc.marks) {
    if (m.to <= from) {
      next.push(m); // entirely before
    } else if (m.from >= to) {
      next.push({ ...m, from: m.from - D, to: m.to - D }); // entirely after
    } else if (m.from >= from && m.to <= to) {
      // fully covered by the deletion: dropped
    } else if (m.from < from && m.to > to) {
      next.push({ ...m, to: m.to - D }); // spans the whole deletion: shrinks
    } else if (m.from < from) {
      next.push({ ...m, to: from }); // straddles the left boundary: trimmed
    } else {
      next.push({ ...m, from, to: m.to - D }); // straddles the right boundary
    }
  }
  doc.marks = normalizeMarks(next);
}

// ---------------------------------------------------------------------------
// public operations — each returns its inverse operation
// ---------------------------------------------------------------------------

export function insertText(doc: Doc, pos: number, str: string): Op {
  return applyOp(doc, { steps: [{ t: 'insert', pos, str }] });
}

export function deleteRange(doc: Doc, from: number, to: number): Op {
  return applyOp(doc, {
    steps: [{ t: 'delete', from, to, str: doc.text.slice(from, to) }],
  });
}

export function addMark(
  doc: Doc,
  from: number,
  to: number,
  type: string,
  attrs?: MarkAttrs,
): Op {
  const kept: MarkRange[] = [];
  let lo = from;
  let hi = to;
  for (const m of doc.marks) {
    if (m.type !== type) {
      kept.push(m);
      continue;
    }
    if (!attrsEqual(m.attrs, attrs)) {
      // same type but different attrs: clip it out of the added region
      kept.push(...subtractRange(m, from, to));
    } else {
      // same type and attrs: absorbed into the new range
      lo = Math.min(lo, m.from);
      hi = Math.max(hi, m.to);
    }
  }
  if (hi > lo) {
    kept.push({ from: lo, to: hi, type, ...(attrs ? { attrs: { ...attrs } } : {}) });
  }
  return applyOp(doc, { steps: [{ t: 'setMarks', marks: normalizeMarks(kept) }] });
}

export function removeMark(doc: Doc, from: number, to: number, type: string): Op {
  const kept: MarkRange[] = [];
  for (const m of doc.marks) {
    if (m.type !== type) {
      kept.push(m);
    } else {
      kept.push(...subtractRange(m, from, to));
    }
  }
  return applyOp(doc, { steps: [{ t: 'setMarks', marks: normalizeMarks(kept) }] });
}
"})
