result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/richmodel/src/history.ts", "content": "import { applyOp, type Doc, type Op } from './doc';

/**
 * Undo/redo history for a single document.
 *
 * Operations are recorded by pushing their inverse onto the undo stack.
 * `undo` applies the inverse and pushes the inverse-of-the-inverse (i.e. the
 * redoable forward op) onto the redo stack, and vice versa.
 */
export class History {
  private undoStack: Op[] = [];
  private redoStack: Op[] = [];

  constructor(private readonly doc: Doc) {}

  /** Record the inverse returned by a document operation. Clears redo. */
  record(inverse: Op): void {
    this.undoStack.push(inverse);
    this.redoStack = [];
  }

  get canUndo(): boolean {
    return this.undoStack.length > 0;
  }

  get canRedo(): boolean {
    return this.redoStack.length > 0;
  }

  /** Apply the most recent inverse; returns false if nothing to undo. */
  undo(): boolean {
    const op = this.undoStack.pop();
    if (!op) return false;
    this.redoStack.push(applyOp(this.doc, op));
    return true;
  }

  /** Re-apply the most recently undone operation; returns false if impossible. */
  redo(): boolean {
    const op = this.redoStack.pop();
    if (!op) return false;
    this.undoStack.push(applyOp(this.doc, op));
    return true;
  }
}
"})
