result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/richmodel/test/doc.test.ts", "content": "import { describe, expect, it } from 'vitest';
import {
  addMark,
  createEmptyDoc,
  deleteRange,
  insertText,
  cloneDoc,
  removeMark,
  type Doc,
  type MarkRange,
} from '../src/doc';
import { History } from '../src/history';

function doc(text: string, marks: MarkRange[] = []): Doc {
  return { text, marks };
}

// ---------------------------------------------------------------------------
// insertText mark math
// ---------------------------------------------------------------------------

describe('insertText', () => {
  it('grows a bold mark when inserted strictly inside', () => {
    const d = doc('hello', [{ from: 1, to: 4, type: 'bold' }]);
    insertText(d, 2, 'XY');
    expect(d.text).toBe('hXYello');
    expect(d.marks).toEqual([{ from: 1, to: 6, type: 'bold' }]);
  });

  it('grows a link mark when inserted strictly inside (inside is always inside)', () => {
    const d = doc('hello', [{ from: 1, to: 4, type: 'link', attrs: { href: 'x' } }]);
    insertText(d, 2, 'XY');
    expect(d.marks).toEqual([
      { from: 1, to: 6, type: 'link', attrs: { href: 'x' } },
    ]);
  });

  it('extends an inclusive bold mark when inserted at its start', () => {
    const d = doc('hello', [{ from: 1, to: 4, type: 'bold' }]);
    insertText(d, 1, 'XY');
    expect(d.marks).toEqual([{ from: 1, to: 6, type: 'bold' }]);
  });

  it('does not extend a non-inclusive link when inserted at its start', () => {
    const d = doc('hello', [{ from: 1, to: 4, type: 'link', attrs: { href: 'x' } }]);
    insertText(d, 1, 'XY');
    expect(d.text).toBe('hXYello');
    expect(d.marks).toEqual([
      { from: 3, to: 6, type: 'link', attrs: { href: 'x' } },
    ]);
  });

  it('extends an inclusive bold mark when inserted at its end', () => {
    const d = doc('hello', [{ from: 1, to: 4, type: 'bold' }]);
    insertText(d, 4, 'XY');
    expect(d.marks).toEqual([{ from: 1, to: 6, type: 'bold' }]);
  });

  it('does not extend a non-inclusive link when inserted at its end', () => {
    const d = doc('hello', [{ from: 1, to: 4, type: 'link', attrs: { href: 'x' } }]);
    insertText(d, 4, 'XY');
    expect(d.marks).toEqual([
      { from: 1, to: 4, type: 'link', attrs: { href: 'x' } },
    ]);
  });

  it('shifts all marks when inserted before them', () => {
    const d = doc('hello', [
      { from: 1, to: 2, type: 'bold' },
      { from: 3, to: 5, type: 'link', attrs: { href: 'x' } },
    ]);
    insertText(d, 0, 'AB');
    expect(d.marks).toEqual([
      { from: 3, to: 4, type: 'bold' },
      { from: 5, to: 7, type: 'link', attrs: { href: 'x' } },
    ]);
  });

  it('inverse restores the document exactly', () => {
    const before = doc('hello', [{ from: 1, to: 4, type: 'bold' }]);
    const d = cloneDoc(before);
    const inv = insertText(d, 2, 'world');
    expect(d.text).toBe('hworlldo'.replace('worl', 'world')); // sanity below
    applyAndCheckInverse(d, before, inv);
  });
});

// small helper used by the tests: apply inverse, compare, redo via second inverse
function applyAndCheckInverse(d: Doc, expected: Doc, inv: ReturnType<typeof insertText>) {
  // applying the returned op must restore `expected`
  const redo = require('../src/doc').applyOp(d, inv) as ReturnType<typeof insertText>;
  expect(d).toStrictEqual(expected);
  // and the inverse of the inverse must reproduce the forward state
  require('../src/doc').applyOp(d, redo);
  expect(d.text.length).toBeGreaterThan(0 || expected.text.length); // no-op guard
}

// ---------------------------------------------------------------------------
// deleteRange
// ---------------------------------------------------------------------------

describe('deleteRange', () => {
  it('trims a mark straddling the left deletion boundary', () => {
    const d = doc('hello', [{ from: 1, to: 4, type: 'bold' }]);
    deleteRange(d, 3, 5); // remove "lo"
    expect(d.text).toBe('hel');
    expect(d.marks).toEqual([{ from: 1, to: 3, type: 'bold' }]);
  });

  it('trims a mark straddling the right deletion boundary', () => {
    const d = doc('hello', [{ from: 1, to: 4, type: 'bold' }]);
    deleteRange(d, 0, 2); // remove "he"
    expect(d.text).toBe('llo');
    expect(d.marks).toEqual([{ from: 0, to: 2, type: 'bold' }]);
  });

  it('shrinks a mark that spans the entire deleted range', () => {
    const d = doc('abcdef', [{ from: 0, to: 6, type: 'italic' }]);
    deleteRange(d, 2, 4);
    expect(d.marks).toEqual([{ from: 0, to: 4, type: 'italic' }]);
  });

  it('drops a mark fully covered by the deletion', () => {
    const d = doc('hello', [
      { from: 2, to: 4, type: 'bold' },
      { from: 4, to: 5, type: 'italic' },
    ]);
    deleteRange(d, 1, 4);
    expect(d.marks).toEqual([{ from: 3, to: 4, type: 'italic' }]);
  });

  it('shifts later marks left', () => {
    const d = doc('hello', [{ from: 3, to: 5, type: 'link', attrs: { href: 'x' } }]);
    deleteRange(d, 0, 2);
    expect(d.marks).toEqual([{ from: 1, to: 3, type: 'link', attrs: { href: 'x' } }]);
  });

  it('deleting a gap makes adjacent identical marks merge', () => {
    const d = doc('abcdef', [
      { from: 0, to: 2, type: 'bold', attrs: { w: 700 } },
      { from: 4, to: 6, type: 'bold', attrs: { w: 700 } },
    ]);
    deleteRange(d, 2, 4);
    expect(d.marks).toEqual([{ from: 0, to: 4, type: 'bold', attrs: { w: 700 } }]);
  });

  it('inverse restores text and marks exactly', () => {
    const before = doc('hello world', [
      { from: 0, to: 5, type: 'bold' },
      { from: 6, to: 11, type: 'link', attrs: { href: 'y' } },
    ]);
    const d = cloneDoc(before);
    const { applyOp } = require('../src/doc') as typeof import('../src/doc');
    const inv = deleteRange(d, 2, 9);
    applyOp(d, inv);
    expect(d).toStrictEqual(before);
  });
});

// ---------------------------------------------------------------------------
// merge behavior
// ---------------------------------------------------------------------------

describe('mark merging', () => {
  it('addMark adjacent to an identical range merges into one', () => {
    const d = doc('abcd', [{ from: 0, to: 2, type: 'bold' }]);
    addMark(d, 2, 4, 'bold');
    expect(d.marks).toEqual([{ from: 0, to: 4, type: 'bold' }]);
  });

  it('adjacent ranges with same type but different attrs do not merge', () => {
    const d = doc('abcd', [{ from: 0, to: 2, type: 'link', attrs: { href: 'a' } }]);
    addMark(d, 2, 4, 'link', { href: 'b' });
    expect(d.marks).toEqual([
      { from: 0, to: 2, type: 'link', attrs: { href: 'a' } },
      { from: 2, to: 4, type: 'link', attrs: { href: 'b' } },
    ]);
  });

  it('adjacent links with equal attrs merge', () => {
    const d = doc('abcd');
    addMark(d, 0, 2, 'link', { href: 'a' });
    addMark(d, 2, 4, 'link', { href: 'a' });
    expect(d.marks).toEqual([{ from: 0, to: 4, type: 'link', attrs: { href: 'a' } }]);
  });

  it('overlapping identical ranges are absorbed', () => {
    const d = doc('abcde', [{ from: 0, to: 3, type: 'bold' }]);
    addMark(d, 2, 5, 'bold');
    expect(d.marks).toEqual([{ from: 0, to: 5, type: 'bold' }]);
  });

  it('removeMark splits a range and re-adding merges it back', () => {
    const d = doc('abcdef', [{ from: 0, to: 6, type: 'bold' }]);
    removeMark(d, 2, 4, 'bold');
    expect(d.marks).toEqual([
      { from: 0, to: 2, type: 'bold' },
      { from: 4, to: 6, type: 'bold' },
    ]);
    addMark(d, 2, 4, 'bold');
    expect(d.marks).toEqual([{ from: 0, to: 6, type: 'bold' }]);
  });
});

// ---------------------------------------------------------------------------
// operation inverses
// ---------------------------------------------------------------------------

describe('inverses', () => {
  it('addMark inverse removes exactly what was added', () => {
    const before = doc('hello');
    const d = cloneDoc(before);
    const { applyOp } = require('../src/doc') as typeof import('../src/doc');
    const inv = addMark(d, 1, 4, 'bold');
    expect(d.marks).toEqual([{ from: 1, to: 4, type: 'bold' }]);
    applyOp(d, inv);
    expect(d).toStrictEqual(before);
  });

  it('removeMark inverse restores split ranges with their attrs', () => {
    const before = doc('abcdef', [{ from: 0, to: 6, type: 'link', attrs: { href: 'z' } }]);
    const d = cloneDoc(before);
    const { applyOp } = require('../src/doc') as typeof import('../src/doc');
    const inv = removeMark(d, 2, 4, 'link');
    expect(d.marks).toEqual([
      { from: 0, to: 2, type: 'link', attrs: { href: 'z' } },
      { from: 4, to: 6, type: 'link', attrs: { href: 'z' } },
    ]);
    applyOp(d, inv);
    expect(d).toStrictEqual(before);
  });

  it('double application of an op then its inverse then its inverse round-trips', () => {
    const start = doc('one two three', [{ from: 0, to: 3, type: 'bold' }]);
    const d = cloneDoc(start);
    const { applyOp } = require('../src/doc') as typeof import('../src/doc');
    const i1 = insertText(d, 3, '!!!');
    const i2 = applyOp(d, i1);
    expect(d).toStrictEqual(start);
    const i3 = applyOp(d, i2);
    expect(d.text).toBe('one!!! two three');
    expect(d.marks).toEqual([{ from: 0, to: 6, type: 'bold' }]);
    applyOp(d, i3);
    expect(d).toStrictEqual(start);
  });
});

// ---------------------------------------------------------------------------
// randomized do-then-undo test
// ---------------------------------------------------------------------------

/** Deterministic PRNG so failures are reproducible. */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const TYPES = ['bold', 'italic', 'link'] as const;

function randomDoc(rng: () => number): Doc {
  const len = 8 + Math.floor(rng() * 20);
  let text = '';
  for (let i = 0; i < len; i++) text += 'abcdefghijklmnop'[Math.floor(rng() * 16)];
  const marks: MarkRange[] = [];
  const n = Math.floor(rng() * 5);
  for (let i = 0; i < n; i++) {
    const a = Math.floor(rng() * len);
    const b = Math.floor(rng() * len);
    if (a === b) continue;
    const type = TYPES[Math.floor(rng() * TYPES.length)]!;
    marks.push({
      from: Math.min(a, b),
      to: Math.max(a, b),
      type,
      ...(type === 'link' ? { attrs: { href: `h${i}` } } : {}),
    });
  }
  return { text, marks };
}

function randomStep(rng: () => number, d: Doc): void {
  const len = d.text.length;
  const kind = Math.floor(rng() * 4);
  if (kind === 0) {
    const pos = Math.floor(rng() * (len + 1));
    let str = '';
    const sl = 1 + Math.floor(rng() * 4);
    for (let i = 0; i < sl; i++) str += 'xyzw'[Math.floor(rng() * 4)];
    return void insertText(d, pos, str);
  }
  if (kind === 1) {
    const a = Math.floor(rng() * (len + 1));
    const b = Math.floor(rng() * (len + 1));
    return void deleteRange(d, Math.min(a, b), Math.max(a, b));
  }
  if (kind === 2) {
    const a = Math.floor(rng() * (len + 1));
    const b = Math.floor(rng() * (len + 1));
    const type = TYPES[Math.floor(rng() * TYPES.length)]!;
    const useAttrs = rng() < 0.5;
    return void addMark(d, Math.min(a, b), Math.max(a, b), type, useAttrs ? { k: 1 } : undefined);
  }
  const a = Math.floor(rng() * (len + 1));
  const b = Math.floor(rng() * (len + 1));
  const type = TYPES[Math.floor(rng() * TYPES.length)]!;
  return void removeMark(d, Math.min(a, b), Math.max(a, b), type);
}

describe('randomized do-then-undo', () => {
  it('20 random operations undo back to the initial document (and redo forward)', () => {
    const rng = mulberry32(20260824);
    const initial = randomDoc(rng);
    const d = cloneDoc(initial);
    const history = new History(d);

    for (let i = 0; i < 20; i++) randomStep(rng, d);

    const afterOps = cloneDoc(d);

    // undo everything
    let undos = 0;
    while (history.undo()) undos++;
    expect(undos).toBe(20);
    expect(d).toStrictEqual(initial);

    // redo everything
    let redos = 0;
    while (history.redo()) redos++;
    expect(redos).toBe(20);
    expect(d).toStrictEqual(afterOps);

    // and undo again for good measure
    while (history.undo());
    expect(d).toStrictEqual(initial);
  });

  it('multiple seeds all round-trip', () => {
    for (let seed = 1; seed <= 25; seed++) {
      const rng = mulberry32(seed * 7919);
      const initial = randomDoc(rng);
      const d = cloneDoc(initial);
      const history = new History(d);
      for (let i = 0; i < 20; i++) randomStep(rng, d);
      while (history.undo());
      expect(d).toStrictEqual(initial);
    }
  });
});
"})
print(result)

