export function normalizeMarks(marks: MarkRange[]): MarkRange[] {
  // Union the intervals of every (type, attrs) group independently, then
  // flatten and sort. This merges overlapping identical ranges even when
  // they are interleaved with other marks in sort order.
  const groups = new Map<string, { type: string; attrs?: MarkAttrs; iv: Array<[number, number]> }>();
  for (const m of marks) {
    if (m.to <= m.from) continue;
    const attrsKey = m.attrs
      ? JSON.stringify(Object.keys(m.attrs).sort().map((k) => [k, m.attrs![k]]))
      : '';
    const key = `${m.type}\u0000${attrsKey}`;
    let g = groups.get(key);
    if (!g) {
      g = {
        type: m.type,
        ...(m.attrs ? { attrs: { ...m.attrs } } : {}),
        iv: [],
      };
      groups.set(key, g);
    }
    g.iv.push([m.from, m.to]);
  }
  const out: MarkRange[] = [];
  for (const g of groups.values()) {
    g.iv.sort((a, b) => a[0]! - b[0]! || a[1]! - b[1]!);
    let cur = g.iv[0]!;
    for (const iv of g.iv.slice(1)) {
